from zalib import *
U=lambda v:v/np.linalg.norm(v)
F5=['first','second','third','fourth','fifth'];mc=[f.capitalize()+' metacarpal bone' for f in F5]
pp=['Proximal phalanx of %s finger of hand'%f for f in F5];mp=['Middle phalanx of %s finger of hand'%f for f in F5[1:]];dp=['Distal phalanx of %s finger of hand'%f for f in F5]
carp=['Capitate bone','Hamate bone','Lunate bone','Pisiform bone','Trapezoid bone','Triquetrum bone']
cap=cen('Capitate bone');frc=cen('Flexor retinaculum of wrist')
dist=U(cen(mc[2])-cen('Radius'))
palm=frc-cap;palm=U(palm-dist*(palm@dist));rad=U(np.cross(dist,palm))
if rad@(cen(mc[0])-cen(mc[4]))<0: rad=-rad
uln=-rad;dors=-palm;prox=-dist
mcp=[near(mc[i],pp[i]) for i in range(5)]
pip=[near(pp[i+1],mp[i]) for i in range(4)];dip=[near(mp[i],dp[i+1]) for i in range(4)]
ipp=near(pp[0],dp[0]);tm=near('Trapezium bone',mc[0]);sl=cen('Scapholunate interosseous ligament')
pis=cen('Pisiform bone');sca=cen('Scaphoid bone')
J=Joint('main','Poignet et main','Poignet et main droits',mix(cap,mcp[2],.35),380)
J.use()
J.bone('radius','Radius','Radius',cap=5000);J.bone('ulna','Ulna','Ulna',cap=5000)
J.bone('carpe','Os du carpe',carp,cap=1600);J.bone('scaph','Scaphoïde','Scaphoid bone',cap=1800);J.bone('trapeze','Trapèze','Trapezium bone',cap=1600)
J.bone('meta','Métacarpiens',mc,cap=2200);J.bone('phal','Phalanges',pp+mp+dp,cap=1300)
J.real('ret','Rétinaculum des fléchisseurs','lig','Flexor retinaculum of wrist')
J.real('retext','Rétinaculum des extenseurs','lig','Extensor retinaculum of wrist',op=.5)
J.real('gcarp','Gaine commune des fléchisseurs','ten','Common flexor tendon sheath',color='#f6efe0',op=.45)
J.real('gdq','Gaine des tendons du pouce','ten','Tendon sheath - abd. pollicis longus - ext. pollicis brevis',color='#f6efe0',op=.8)
J.real('gecu','Gaine de l’extenseur ulnaire du carpe','ten','Tendon sheath of extensor carpi ulnaris',color='#f6efe0',op=.8)
J.real('gdoigt','Gaines des fléchisseurs dans les doigts','ten','Synovial sheaths of digits of hand',color='#f6efe0',op=.6,cap=5000)
J.real('poulies','Poulies des doigts','lig','Cruciform part of fibrous sheath of digit of hand',cap=3000)
J.real('tfcc','Disque du complexe triangulaire','cart','Articular disc of distal radio-ulnar joint',color='#9fd8ee',op=.95)
J.real('lsl','Ligament scapho-lunaire','lig','Scapholunate interosseous ligament')
J.real('ldors','Ligaments dorsaux du poignet','lig',['Dorsal radiocarpal ligament','Dorsal intercarpal ligaments'],op=.6)
J.real('apon','Aponévrose palmaire','lig','Palmar aponeurosis',color='#e9c46a',op=.7,cap=4000)
J.real('cap-ip','Capsules des articulations des doigts','lig',['Articular capsules of distal interphalangeal joints','Articular capsules of proximal interphalangeal joints'],color='#cfe3ee',op=.6,cap=3000)
J.real('cap-mcp','Capsules à la base des doigts','lig','Articular capsules of metacarpophalangeal joints',color='#cfe3ee',op=.35,cap=3000)
J.real('lph','Ligament piso-hamatum (canal de Guyon)','lig','Pisohamate ligament')
J.mus('pouce','Long abducteur et court extenseur du pouce',['Abductor pollicis longus','Extensor pollicis brevis'],tlabel='Tendons du long abducteur et du court extenseur du pouce')
J.mus('epl','Long extenseur du pouce','Extensor pollicis longus')
J.mus('flech','Fléchisseurs des doigts',['Flexor digitorum profundus','Humero-ulnar head of flexor digitorum superficialis','Radial head of flexor digitorum superficialis','Flexor pollicis longus'],tlabel='Tendons fléchisseurs des doigts',cap=7000)
J.mus('ext','Extenseurs des doigts',['Extensor digitorum','Extensor indicis','Extensor digiti minimi'],tlabel='Tendons extenseurs des doigts',cap=6000)
J.mus('ecu','Extenseur ulnaire du carpe',['Humeral head of extensor carpi ulnaris','Ulnar head of extensor carpi ulnaris'],tlabel='Tendon de l’extenseur ulnaire du carpe')
J.mus('ecr','Extenseurs radiaux du carpe',['Extensor carpi radialis longus','Extensor carpi radialis brevis'])
J.mus('fcr','Fléchisseurs du carpe',['Flexor carpi radialis','Humeral head of flexor carpi ulnaris','Ulnar head of flexor carpi ulnaris','Palmaris longus muscle'])
J.mus('then','Muscles de la base du pouce',['Abductor pollicis brevis','Opponens pollicis muscle','Superficial head of flexor pollicis brevis','Deep head of flexor pollicis brevis','Oblique head of adductor pollicis','Transverse head of adductor pollicis'])
J.mus('hypo','Muscles de la base du petit doigt',['Abductor digiti minimi of hand','Flexor digiti minimi of hand','Opponens digiti minimi muscle of hand'])
J.mus('inter','Interosseux et lombricaux',['Dorsal interossei muscles of hand','Lumbrical muscles of hand','Palmar interossei muscles'])
J.real('nm','Nerf médian et ses branches','nerf',['Median nerve','Common palmar digital branches of median nerve','Proper palmar digital branches of median nerve'],cap=3000)
J.real('nu','Nerf ulnaire et ses branches','nerf',['Ulnar nerve','Deep branch of ulnar nerve','Superficial branch of ulnar nerve','Common palmar digital branches of ulnar nerve','Proper palmar digital branches of ulnar nerve'],cap=2500)
J.real('nrs','Branche superficielle du nerf radial','nerf','Superficial branch of radial nerve',cap=1200)
J.blob('kyste','Kyste synovial dorsal, lorsqu’il existe','cart',sl+dors*11,(8,8,7),op=.6)
J.skin([mix(cap,mcp[2],.6),cap+prox*60],150,cap=12000)
sty=ext('Radius',dist+rad*.6,frac=.02);uh=ext('Ulna',dist,frac=.03)
dq=cen('Tendon sheath - abd. pollicis longus - ext. pollicis brevis');ecu=cen('Tendon sheath of extensor carpi ulnaris');tf=cen('Articular disc of distal radio-ulnar joint')
nm_t=snap('Median nerve',frc-palm*3);guy=cen('Pisohamate ligament');nu_g=snap('Ulnar nerve',guy)
a1=[mcp[i]+palm*7+prox*3 for i in (2,3)]
for a in [('doigts','w','Dans les doigts'),('pouce','w','À la base du pouce'),('paume','w','Dans la paume'),('dos','w','Sur le dos du poignet'),('bordp','w','Au bord du poignet côté pouce'),('bord5','w','Au bord du poignet côté petit doigt'),
 ('nuit','q','Fourmillements la nuit'),('f123','q','Fourmillements du pouce, de l’index, du majeur'),('f45','q','Fourmillements du petit doigt'),('pince','q','En pinçant ou en tournant une clé'),('accroche','q','Un doigt accroche ou se bloque'),('boule','q','Une boule ou une corde est apparue'),('chute','q','Après une chute sur la main'),('appui','q','En appui sur la main'),('raide','q','Doigts raides, nodosités'),('porter','q','En portant un bébé ou en essorant'),('tourner','q','En tournant l’avant-bras')]: J.sym(*a)
p=J.p
p('arthmain',['c-phal','cap-ip','phal'],[(q,9) for q in dip]+[(q,8) for q in pip[:2]],[(mix(dip[0],dip[3])+dors*4,34),(mix(pip[0],pip[1])+dors*4,22)],tags=['doigts','raide','pince'],view='dos')
p('carpien',['nm','ret'],[(nm_t,19)],[(frc+palm*6,24),(mix(mcp[1],mcp[2])+palm*8,30),(mix(pip[0],pip[1])+palm*5,34),(ipp+palm*4,20)],tags=['paume','doigts','nuit','f123'])
p('rhiz',['c-trapeze','c-meta','trapeze','m-then'],[(tm,14)],[(tm+rad*5,26)],tags=['pouce','pince'])
p('ressaut',['poulies','gdoigt','t-flech'],[(a1[0],12),(a1[1],10)],[(mix(mcp[2],mcp[3])+palm*9,22)],tags=['paume','doigts','accroche'])
p('quervain',['gdq','t-pouce','m-pouce'],[(dq,17)],[(dq+rad*4,26),(dq+prox*38,22)],tags=['bordp','pouce','porter','pince'],view='cote')
p('kyste',['kyste','lsl','ldors'],[(sl+dors*11,15)],[(sl+dors*15,22)],tags=['dos','boule','appui'],view='dos')
p('entorse',['lsl','ldors','c-scaph','c-carpe'],[(sl,15)],[(sl+dors*8,30)],tags=['dos','chute','appui'],view='dos')
p('dupuytren',['apon'],[(mix(frc,mcp[3])+palm*8,20),(mcp[3]+palm*9,15),(mcp[4]+palm*9,13)],[(mix(frc,mcp[3],.75)+palm*10,28)],tags=['paume','boule'])
p('ecu',['gecu','t-ecu','m-ecu'],[(ecu,17)],[(ecu+dors*4+uln*4,26)],tags=['bord5','dos','tourner'],view='dos')
p('tfcc',['tfcc'],[(tf,13)],[(tf+uln*6,24)],tags=['bord5','appui','tourner','chute'])
p('scaphoide',['scaph'],[(sca,14)],[(sca+dors*5+rad*4,22)],tags=['bordp','pouce','chute','appui'],view='cote')
p('guyon',['nu','lph'],[(nu_g,14)],[(guy+palm*5,20),(mcp[4]+palm*8,22),(mcp[4]+dist*45+palm*4,24)],tags=['bord5','paume','f45','appui'])
J.write()
